package orm

import (
	"fmt"
	"reflect"
	"slices"
	"sync"
)

// Mapper is implemented by models with mappers generated by orm-gen
// (`//go:generate go run orm-gen`): the orm then reads and writes the
// model's columns through these methods instead of reflection. All four
// methods are generated together, on the pointer receiver; there is no
// reason to write them by hand.
//
// The columns are those of the `db` tags in field order, embedded structs
// included, exactly as the orm finds them by reflection. If the struct
// changes and the mappers are not regenerated, the orm notices the
// difference in OrmColumns and returns an error instead of scanning into the
// wrong fields.
type Mapper interface {
	// OrmColumns returns the columns in field order (duplicates kept).
	OrmColumns() []string
	// OrmScanTargets returns pointers to the fields of OrmColumns, in order,
	// for Rows.Scan.
	OrmScanTargets() []any
	// OrmValues returns every column's value; a duplicated column has the
	// value of its first field.
	OrmValues() map[string]any
	// OrmFill sets the fields from a document (NoSQL drivers): missing and
	// nil values are skipped, others are converted with Assign.
	OrmFill(row map[string]any) error
}

// Assign stores raw in *dst, as FillStruct does for one field: a value of
// the field's type is stored as is, others are converted (JSON float64 to
// int64, RFC 3339 strings to time.Time, a value to a pointer field, …);
// nil leaves *dst unchanged. Used by the code orm-gen generates.
func Assign[T any](dst *T, raw any) error {
	if raw == nil {
		return nil
	}
	if v, ok := raw.(T); ok {
		*dst = v
		return nil
	}
	return assignValue(reflect.ValueOf(dst).Elem(), raw)
}

var mapperType = reflect.TypeOf((*Mapper)(nil)).Elem()

// plan is the cached mapping of a struct type: its `db` fields in order.
type plan struct {
	cols   []string
	fields []planField
	mapper bool  // *T implements Mapper with matching columns
	err    error // the generated mappers are out of date
}

type planField struct {
	path []int
	col  string
	name string
}

var planCache sync.Map // reflect.Type → *plan

// planOf walks t once: exported fields with a `db` tag other than "-",
// embedded exported (or unexported) structs recursively, embedded structs
// reached through an unexported embedding skipped (their fields cannot be set).
func planOf(t reflect.Type) *plan {
	if p, ok := planCache.Load(t); ok {
		return p.(*plan)
	}
	p := &plan{}
	var walk func(rt reflect.Type, prefix []int)
	walk = func(rt reflect.Type, prefix []int) {
		for i := 0; i < rt.NumField(); i++ {
			f := rt.Field(i)
			path := append(append([]int(nil), prefix...), i)
			if f.Anonymous && f.Type.Kind() == reflect.Struct {
				if f.IsExported() {
					walk(f.Type, path)
				}
				continue
			}
			tag := f.Tag.Get("db")
			if !f.IsExported() || tag == "" || tag == "-" {
				continue
			}
			p.cols = append(p.cols, tag)
			p.fields = append(p.fields, planField{path: path, col: tag, name: f.Name})
		}
	}
	walk(t, nil)
	if reflect.PointerTo(t).Implements(mapperType) {
		gen := reflect.New(t).Interface().(Mapper).OrmColumns()
		if slices.Equal(gen, p.cols) {
			p.mapper = true
		} else {
			p.err = fmt.Errorf("orm: the generated mappers of %s are out of date (columns %v, the struct has %v); run go generate", t, gen, p.cols)
		}
	}
	actual, _ := planCache.LoadOrStore(t, p)
	return actual.(*plan)
}

// scanTargets returns the scan destinations of a pointer to a struct.
func scanTargets(dest any) ([]any, error) {
	v := reflect.ValueOf(dest).Elem()
	p := planOf(v.Type())
	if p.err != nil {
		return nil, p.err
	}
	if p.mapper {
		return dest.(Mapper).OrmScanTargets(), nil
	}
	out := make([]any, len(p.fields))
	for i, f := range p.fields {
		out[i] = v.FieldByIndex(f.path).Addr().Interface()
	}
	return out, nil
}

// fillValue sets the fields of an addressable struct value from m.
func fillValue(v reflect.Value, m map[string]any) error {
	p := planOf(v.Type())
	if p.err != nil {
		return p.err
	}
	if p.mapper {
		return v.Addr().Interface().(Mapper).OrmFill(m)
	}
	for _, f := range p.fields {
		raw, ok := m[f.col]
		if !ok || raw == nil {
			continue
		}
		if err := assignValue(v.FieldByIndex(f.path), raw); err != nil {
			return fmt.Errorf("orm: field %q (db:%q): %w", f.name, f.col, err)
		}
	}
	return nil
}
